package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;
/** Root plus unticked shape cells. Only the twelve moving-door cells carry a door pose. */
public class Ps01Block extends BaseEntityBlock{
 public static final DirectionProperty FACING=BlockStateProperties.HORIZONTAL_FACING;public static final BooleanProperty LIT=BlockStateProperties.LIT;public static final IntegerProperty BODY_PART=IntegerProperty.create("part",0,Ps01Geometry.BODY.length-1),DOOR_PART=IntegerProperty.create("part",0,Ps01Geometry.DOOR.length-1),STEP=IntegerProperty.create("door",0,19);static final ThreadLocal<Boolean>MUTATING=ThreadLocal.withInitial(()->false);public final boolean door;
 public Ps01Block(Properties p,boolean moving){super(p);door=moving;var s=stateDefinition.any().setValue(FACING,Direction.NORTH).setValue(LIT,false);s=s.setValue(moving?DOOR_PART:BODY_PART,0);if(moving)s=s.setValue(STEP,0);registerDefaultState(s);}
 @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(FACING,LIT);if(getClass()==Ps01DoorBlock.class)b.add(DOOR_PART,STEP);else b.add(BODY_PART);}
 public static BlockPos root(BlockPos p,BlockState s){var b=(Ps01Block)s.getBlock();return Ps01Geometry.root(p,s.getValue(FACING),(b.door?Ps01Geometry.DOOR:Ps01Geometry.BODY)[s.getValue(b.door?DOOR_PART:BODY_PART)]);}
 public static Ps01BlockEntity main(Level l,BlockPos p,BlockState s){var r=root(p,s);return l.hasChunkAt(r)&&l.getBlockEntity(r)instanceof Ps01BlockEntity b?b:null;}
 @Override public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(FACING,Ps01Item.face(c.getPlayer(),c.getItemInHand()));}
 @Override public void setPlacedBy(Level l,BlockPos p,BlockState s,LivingEntity placer,ItemStack item){if(l.getBlockEntity(p)instanceof Ps01BlockEntity b){if(Ps01Item.data(item).contains("ShelterState"))b.restore(Ps01Item.data(item).getCompound("ShelterState"));if(b.owner==null&&placer!=null)b.owner=placer.getUUID();if(l instanceof net.minecraft.server.level.ServerLevel server)Ps01WorldData.get(server).add(p,s.getValue(FACING));b.refreshParts();b.changed();}}
 @Override public InteractionResult use(BlockState s,Level l,BlockPos p,Player player,InteractionHand hand,BlockHitResult hit){return interact(s,l,p,player,hand,hit);}
 public InteractionResult interact(BlockState s,Level l,BlockPos p,Player player,InteractionHand hand,BlockHitResult hit){if(player.getItemInHand(hand).getItem()instanceof Ps01Item)return InteractionResult.PASS;var b=main(l,p,s);if(b==null)return InteractionResult.FAIL;if(l.isClientSide)return InteractionResult.SUCCESS;if(player.distanceToSqr(hit.getLocation())>36||!l.mayInteract(player,p)||InjuryHooks.downed(player))return InteractionResult.FAIL;
  var delta=hit.getLocation().subtract(player.getEyePosition());var ray=l.clip(new ClipContext(player.getEyePosition(),hit.getLocation().add(delta.normalize().scale(.03)),ClipContext.Block.OUTLINE,ClipContext.Fluid.NONE,player));if(ray.getType()!=HitResult.Type.BLOCK||!ray.getBlockPos().equals(p)||ray.getLocation().distanceToSqr(hit.getLocation())>.09)return InteractionResult.FAIL;
  var held=player.getItemInHand(hand);if(player.isShiftKeyDown()&&held.is(com.atsuishio.superbwarfare.init.ModTags.Items.TOOLS_CROWBAR)){if(!b.remove(player,true,false))player.displayClientMessage(net.minecraft.network.chat.Component.literal("Only the owner or an operator may remove this shelter"),true);return InteractionResult.CONSUME;}
  var at=Ps01Geometry.local(b.getBlockPos(),b.facing(),hit.getLocation());if(at.z<-2.65&&at.x<.3&&at.x>-1.55&&at.y>.25){b.toggle(player);return InteractionResult.CONSUME;}
  if(Ps01Geometry.inside(b.getBlockPos(),b.facing(),player.position().add(0,.5,0))){int selected=-1;double distance=.9*.9;for(int i=0;i<Ps01Geometry.SEATS.length;i++){var a=Ps01Geometry.SEATS[i];var seat=Ps01Geometry.point(b.getBlockPos(),b.facing(),a[0],a[1],a[2]);double d=seat.distanceToSqr(hit.getLocation());if(d<distance){selected=i;distance=d;}}if(selected>=0){Ps01Seat.sit(b,player,selected);return InteractionResult.CONSUME;}
   if(at.x>.2&&at.x<.65&&at.y>1.3&&at.y<1.85&&at.z>2.38){b.toggleLights();return InteractionResult.CONSUME;}
  }player.displayClientMessage(net.minecraft.network.chat.Component.literal("PS-01 | Structure "+Math.round(b.structure)+" | Door "+Math.round(b.doorHealth)+" | Click the door, a bench or the interior switch"),true);return InteractionResult.CONSUME;
 }
 // Explosion terrain callbacks must not dismantle a whole structure through one cell.
 // The server explosion event applies claim-checked, bounded structural durability wear.
 @Override public void onBlockExploded(BlockState state,Level level,BlockPos pos,Explosion explosion){}
 @Override public void onProjectileHit(Level l,BlockState s,BlockHitResult hit,net.minecraft.world.entity.projectile.Projectile projectile){super.onProjectileHit(l,s,hit,projectile);Ps01Compat.impact(projectile,hit);}
 @Override public void onRemove(BlockState s,Level l,BlockPos p,BlockState next,boolean moving){if(!s.is(next.getBlock())&&!l.isClientSide&&!MUTATING.get()){var b=main(l,p,s);if(b!=null)b.remove(null,false,!l.restoringBlockSnapshots);else if(l instanceof net.minecraft.server.level.ServerLevel server)Ps01WorldData.get(server).removed(server,root(p,s),s.getValue(FACING));}super.onRemove(s,l,p,next,moving);}
 // After placement, shell integrity governs survival; blast craters may remove footing.
 @Override public void neighborChanged(BlockState s,Level l,BlockPos p,Block changed,BlockPos at,boolean moving){}
 @Override public VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return Ps01Geometry.collision(s.getValue(FACING),door,s.getValue(door?DOOR_PART:BODY_PART),door?s.getValue(STEP):0);}@Override public VoxelShape getCollisionShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return getShape(s,l,p,c);}@Override public VoxelShape getOcclusionShape(BlockState s,BlockGetter l,BlockPos p){return Shapes.empty();}@Override public RenderShape getRenderShape(BlockState s){return RenderShape.INVISIBLE;}
 @Override public int getLightBlock(BlockState s,BlockGetter l,BlockPos p){return getShape(s,l,p,CollisionContext.empty()).clip(new Vec3(.5,2,.5),new Vec3(.5,-1,.5),BlockPos.ZERO)==null?0:15;}
 @Override public BlockState rotate(BlockState s,Rotation r){return s.setValue(FACING,r.rotate(s.getValue(FACING)));}
 @Override public BlockState mirror(BlockState s,Mirror m){return rotate(s,m.getRotation(s.getValue(FACING)));}
 @Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return !door&&s.getValue(BODY_PART)==0?new Ps01BlockEntity(p,s):null;}
 @Override public <T extends BlockEntity>BlockEntityTicker<T>getTicker(Level l,BlockState s,BlockEntityType<T>t){return !l.isClientSide&&!door&&s.getValue(BODY_PART)==0?createTickerHelper(t,AddonBlockEntities.PS01.get(),Ps01BlockEntity::tick):null;}
}
